/** CLI-owned; regenerated by setu generate module or setu generate … --module <name>. */
import type { IRouterApi, IServiceRegistry } from '@setu-ts/common';
import { registerNewsRoutes } from './news.controller.ts';

/** Registers the feature routes. */
export function registerNewsModule(router: IRouterApi, services?: IServiceRegistry): void {
  registerNewsRoutes(router, services);
}
